  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum Rol {\n  DIRECTORA\n  VETERINARIA\n  ENCARGADA_ADOPCIONES\n  VOLUNTARIO_AVANZADO\n  VOLUNTARIO_NOVATO\n}\n\nenum EstadoSalud {\n  NORMAL\n  CONDICION_ESPECIAL\n  CRITICO\n}\n\nenum EstadoCanil {\n  LIBRE\n  OCUPADO\n  CUARENTENA\n  MANTENIMIENTO\n}\n\nenum TipoTraslado {\n  INTERNO_CANIL\n  PROTECTORA_ALIADA\n  HOGAR_TEMPORAL\n}\n\nenum EstadoTraslado {\n  PENDIENTE_APROBACION\n  APROBADO\n  RECHAZADO\n  COMPLETADO\n}\n\nenum AccionAuditoria {\n  CREACION\n  MODIFICACION\n  BAJA_LOGICA\n}\n\nmodel Usuario {\n  id        Int      @id @default(autoincrement())\n  email     String   @unique @db.VarChar(120)\n  password  String   @db.VarChar(255)\n  nombre    String   @db.VarChar(100)\n  rol       Rol      @default(VOLUNTARIO_NOVATO)\n  activo    Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  animalesRegistrados  Animal[]\n  trasladosSolicitados Traslado[]  @relation(\"TrasladoSolicitante\")\n  trasladosAprobados   Traslado[]  @relation(\"TrasladoAprobador\")\n  auditorias           Auditoria[]\n\n  @@map(\"usuarios\")\n}\n\nmodel Animal {\n  id             Int         @id @default(autoincrement())\n  nombre         String      @db.VarChar(80)\n  especie        String      @db.VarChar(40)\n  sexo           String      @db.VarChar(20)\n  edad           String      @db.VarChar(50)\n  raza           String?     @default(\"Mestizo\") @db.VarChar(80)\n  peso           Float       @default(0)\n  chip           String?     @unique @db.VarChar(50)\n  estadoSalud    EstadoSalud @default(NORMAL)\n  nota           String?     @db.Text\n  fotoUrl        String?     @db.Text\n  esterilizacion String?     @default(\"NO\") @db.VarChar(50)\n  comportamiento String?     @db.Text\n  activo         Boolean     @default(true) // Baja lógica\n  creadoEn       DateTime    @default(now())\n\n  creadoPorId Int?\n  creadoPor   Usuario? @relation(fields: [creadoPorId], references: [id], onDelete: SetNull)\n\n  // Asignación de Canil actual\n  canilId Int?   @unique\n  canil   Canil? @relation(fields: [canilId], references: [id], onDelete: SetNull)\n\n  traslados  Traslado[]\n  adopciones Adopcion[]\n\n  @@map(\"animales\")\n}\n\nmodel Canil {\n  id        Int         @id @default(autoincrement())\n  codigo    String      @unique @db.VarChar(30) // Ej: \"C-01\", \"G-05\"\n  nombre    String      @db.VarChar(80)\n  sector    String      @default(\"General\") @db.VarChar(60) // Ej: \"Caniles Perros\", \"Gateras\", \"Cuarentena\"\n  tipo      String      @default(\"Perro\") @db.VarChar(40) // \"Perro\", \"Gato\"\n  capacidad Int         @default(1)\n  estado    EstadoCanil @default(LIBRE)\n\n  animalAlojado Animal?\n\n  trasladosOrigen  Traslado[] @relation(\"TrasladoCanilOrigen\")\n  trasladosDestino Traslado[] @relation(\"TrasladoCanilDestino\")\n\n  @@map(\"caniles\")\n}\n\nmodel Traslado {\n  id       Int    @id @default(autoincrement())\n  animalId Int\n  animal   Animal @relation(fields: [animalId], references: [id], onDelete: Cascade)\n\n  tipo   TipoTraslado\n  motivo String         @db.Text // Obligatorio según R1\n  estado EstadoTraslado @default(PENDIENTE_APROBACION)\n\n  // Si es traslado entre caniles\n  canilOrigenId  Int?\n  canilOrigen    Canil? @relation(\"TrasladoCanilOrigen\", fields: [canilOrigenId], references: [id], onDelete: SetNull)\n  canilDestinoId Int?\n  canilDestino   Canil? @relation(\"TrasladoCanilDestino\", fields: [canilDestinoId], references: [id], onDelete: SetNull)\n\n  // Si es a protectora aliada u hogar temporal\n  destinoNombre    String? @db.VarChar(120)\n  destinoContacto  String? @db.VarChar(120)\n  destinoDireccion String? @db.VarChar(200)\n\n  // Auditoría del movimiento\n  responsableId Int\n  responsable   Usuario @relation(\"TrasladoSolicitante\", fields: [responsableId], references: [id])\n\n  // Aprobación por la Directora (si aplica traslado externo)\n  aprobadoPorId        Int?\n  aprobadoPor          Usuario?  @relation(\"TrasladoAprobador\", fields: [aprobadoPorId], references: [id], onDelete: SetNull)\n  fechaAprobacion      DateTime?\n  comentarioAprobacion String?   @db.Text\n\n  fechaRegistro DateTime @default(now())\n\n  @@map(\"traslados\")\n}\n\nmodel Postulante {\n  id        Int      @id @default(autoincrement())\n  nombre    String   @db.VarChar(100)\n  rut       String   @unique @db.VarChar(20)\n  telefono  String?  @db.VarChar(40)\n  email     String?  @db.VarChar(120)\n  direccion String?  @db.VarChar(200)\n  activo    Boolean  @default(true) // Baja lógica\n  creadoEn  DateTime @default(now())\n\n  adopciones Adopcion[]\n\n  @@map(\"postulantes\")\n}\n\nmodel Adopcion {\n  id           Int        @id @default(autoincrement())\n  animalId     Int\n  animal       Animal     @relation(fields: [animalId], references: [id], onDelete: Cascade)\n  postulanteId Int\n  postulante   Postulante @relation(fields: [postulanteId], references: [id], onDelete: Cascade)\n  fecha        DateTime   @default(now())\n  etapa        String     @default(\"Solicitud recibida\") @db.VarChar(60)\n  devolucion   Boolean    @default(false)\n\n  @@map(\"adopciones\")\n}\n\nmodel Insumo {\n  id          Int      @id @default(autoincrement())\n  nombre      String   @db.VarChar(100)\n  categoria   String   @db.VarChar(60)\n  stock       Int      @default(0)\n  stockMinimo Int      @default(5)\n  activo      Boolean  @default(true) // Baja lógica\n  creadoEn    DateTime @default(now())\n\n  @@map(\"insumos\")\n}\n\nmodel Turno {\n  id         Int       @id @default(autoincrement())\n  diaSemana  String    @db.VarChar(20) // \"Lunes\", \"Martes\", etc.\n  franja     String    @db.VarChar(20) // \"Mañana\", \"Tarde\"\n  area       String    @db.VarChar(60) // \"Paseos\", \"Limpieza\", \"Clínica\", etc.\n  voluntario String?   @db.VarChar(100) // Nombre o nulo si descubierto\n  cubierto   Boolean   @default(false)\n  fecha      DateTime?\n\n  @@map(\"turnos\")\n}\n\nmodel Auditoria {\n  id            Int             @id @default(autoincrement())\n  entidad       String          @db.VarChar(60) // \"Animal\", \"Postulante\", \"Insumo\", \"Canil\", \"Traslado\"\n  entidadId     Int?\n  accion        AccionAuditoria // CREACION, MODIFICACION, BAJA_LOGICA\n  valorAnterior Json?\n  valorNuevo    Json?\n  usuarioId     Int?\n  usuario       Usuario?        @relation(fields: [usuarioId], references: [id], onDelete: SetNull)\n  usuarioEmail  String?         @db.VarChar(120)\n  usuarioNombre String?         @db.VarChar(100)\n  fechaHora     DateTime        @default(now())\n  ipAddress     String?         @db.VarChar(50)\n\n  @@map(\"auditorias\")\n}\n",
